INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('35c05af5-dde3-5a2c-8330-c9d1b6a6422c'::uuid, '29796c23-62e8-5136-9641-fec7c93ee773'::uuid, 'Professionnel BTP — offre clé en main', 'Mission de professionnels BTP portée par AL AAIN BOIS, basé à Agadir. Al Ain Bois est votre partenaire de confiance pour tous vos projets de menuiserie. Nous sélectionnons et commercialisons une large gamme d’essences locales et exotiques, parfaitement séchées et calibrées. Notre atelier intégré conçoit et fabrique… La mission couvre typiquement les volets réalisation / accompagnement : Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu, Expertise Professionnel BTP, Suivi jusqu''à livraison de la mission. AL AAIN BOIS intervient à Agadir, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation professionnel btp, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Matériaux & équipements', 'https://lechantier.ma/uploads/media/0fd53e63b1a9.webp', '["https://lechantier.ma/uploads/media/0fd53e63b1a9.webp"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Professionnel BTP", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Agadir"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_ca