nvenu", "Expertise Installation de revêtement mural", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Mohammedia"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1));
