::jsonb, 'devis', NULL, NULL, 'villes', '["Salé"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1));
